//! `xtask test app-imports` (QEMU Q7 plan, Q7-5): a static audit of an APK's arm64 native libraries against the QEMU engine's binding table (atl-native-bridge `bindings::qemu_rows`, generated by its build.rs). Nothing is executed.
//! Each dynamic undefined symbol resolves in the guest linker's order: a library of the same APK, then each DT_NEEDED soname in order -- that soname's table rows (`bound`: Generic / Shim; `trapped`: a Trap row, with its reason), else the `.map.txt` surface of a guest library (libc / libm / libdl of ndk_surface `MAPS`, plus [`GUEST_MAPS`]: code the guest runs translated, no crossing) -- else `unknown`.
//! A weak unknown binds to 0 at load and is listed apart, not gated (the library must test it before calling).
//! Gate: every gated APK has no trapped and no strong unknown import; otherwise it prints each remaining one with the slice that owns it ([`owner`]) and goes red. `--info` APKs are reported, never gated.
//! Limit: names a library resolves by `dlsym` are not imports, so this audit does not see them.

use std::collections::{BTreeMap, BTreeSet};
use std::path::{Path, PathBuf};
use std::process::{Command, ExitCode};

use anyhow::{Context, Result, ensure};
use atl_layout::Layout;
use atl_native_bridge::engine::bindings::{self, Binding};
use object::read::elf::ElfFile64;
use object::{Endianness, Object, ObjectSymbol, elf};

use crate::verdict::{Failure, Verdict};

/// The APK's arm64 native library directory (zip entry prefix).
const LIB_DIR: &str = "lib/arm64-v8a/";
/// The guest ISA of the QEMU table (build.rs `QEMU_GUEST_ARCH`): the `.map.txt` arch tag.
const GUEST_ARCH: &str = "arm64";
/// Default gated APK, relative to the workspace (plan D-Q7-6: the first arm64 app).
const CTR: &str = "apk/cut-the-rope/3.63.0-arm64-v8a/cut-the-rope-3.63.0-arm64-v8a.apk";
/// Default informational APK: the arm64 split of Battle Cats TW in this directory (plan: the second app).
const BC_DIR: &str = "apk/battle-cats-tw/jp.co.ponos.battlecatstw";
const BC_SPLIT_SUFFIX: &str = ".config.arm64_v8a.apk";

#[derive(clap::Args, Debug)]
pub struct Args {
    /// APK to gate (repeatable; default: Cut the Rope 3.63.0 arm64 under the workspace).
    #[arg(long)]
    pub apk: Vec<PathBuf>,
    /// APK to report without gating (repeatable; default: the Battle Cats TW arm64 split).
    #[arg(long)]
    pub info: Vec<PathBuf>,
    /// Print every import with its class, not only the remaining ones.
    #[arg(long)]
    pub verbose: bool,
}

/// One library's dynamic linking surface.
#[derive(Debug, Default, Clone)]
pub struct Elf {
    pub needed: Vec<String>,
    /// (name, weak)
    pub imports: Vec<(String, bool)>,
    pub exports: BTreeSet<String>,
}

/// Where one import resolves.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Class {
    /// defined by a library of the same APK
    App(String),
    /// a Generic or Shim row of that table soname
    Bound(&'static str),
    /// a Trap row: soname, reason
    Trapped(&'static str, &'static str),
    /// the guest library surface of that soname
    Guest(&'static str),
    Unknown {
        weak: bool,
    },
}

/// The table as the audit reads it: (soname, name) -> binding.
pub type Rows = BTreeMap<(&'static str, &'static str), Binding>;

pub fn qemu_rows() -> Rows {
    bindings::qemu_rows().map(|(l, n, b)| ((l, n), b)).collect()
}

/// Resolves `name` from a library whose DT_NEEDED is `needed`; `app` = the other libraries of the APK, `surfaces` = guest library names per soname.
pub fn classify(
    name: &str,
    weak: bool,
    needed: &[String],
    app: &BTreeMap<String, BTreeSet<String>>,
    rows: &Rows,
    surfaces: &BTreeMap<&'static str, BTreeSet<String>>,
) -> Class {
    if let Some((lib, _)) = app.iter().find(|(_, e)| e.contains(name)) {
        return Class::App(lib.clone());
    }
    for so in needed {
        if let Some((&(lib, _), b)) = rows.iter().find(|((l, n), _)| l == so && *n == name) {
            return match b {
                Binding::Trap(why) => Class::Trapped(lib, why),
                Binding::Generic { .. } | Binding::Shim => Class::Bound(lib),
            };
        }
        if let Some((&lib, _)) = surfaces.iter().find(|(l, s)| *l == so && s.contains(name)) {
            return Class::Guest(lib);
        }
    }
    Class::Unknown { weak }
}

/// The slice that owns a remaining import, from the trap reason the table generates (build.rs): GS2.2 classes are deferred (D-Q7-5), R-1 refusals stay refused, the rest has no slice yet.
pub fn owner(c: &Class) -> &'static str {
    match c {
        Class::Trapped(_, why) if why.contains("GS2.2") => "GS2.2 (deferred, D-Q7-5)",
        Class::Trapped(_, why) if why.starts_with("refused") => "R-1 (refused by design)",
        Class::Trapped(..) => "none: needs a binding row",
        _ => "none: not in any table",
    }
}

/// An ELF image's needed sonames, dynamic imports and exports.
pub fn read_elf(data: &[u8]) -> Result<Elf> {
    let file = ElfFile64::<Endianness>::parse(data)?;
    let endian = file.endian();
    let mut out = Elf::default();
    for s in file.dynamic_symbols() {
        let Ok(name) = s.name() else { continue };
        if name.is_empty() {
            continue;
        }
        if s.is_undefined() {
            out.imports.push((name.to_owned(), s.is_weak()));
        } else {
            out.exports.insert(name.to_owned());
        }
    }
    let table = file.elf_section_table().dynamic_table(endian, data)?;
    for d in &table {
        if d.tag == elf::DT_NEEDED {
            out.needed
                .push(String::from_utf8_lossy(table.string(d)?).into_owned());
        }
    }
    Ok(out)
}

/// The arm64 libraries of `apk` (a zip, read through `unzip`).
fn apk_libs(apk: &Path) -> Result<BTreeMap<String, Elf>> {
    let list = Command::new("unzip")
        .arg("-Z1")
        .arg(apk)
        .output()
        .context("running unzip")?;
    ensure!(
        list.status.success(),
        "unzip -Z1 {}: {}",
        apk.display(),
        list.status
    );
    let mut out = BTreeMap::new();
    for entry in String::from_utf8_lossy(&list.stdout).lines() {
        let Some(lib) = entry.strip_prefix(LIB_DIR).filter(|l| l.ends_with(".so")) else {
            continue;
        };
        let data = Command::new("unzip")
            .arg("-p")
            .arg(apk)
            .arg(entry)
            .output()
            .context("running unzip")?;
        ensure!(data.status.success(), "unzip -p {} {entry}", apk.display());
        out.insert(
            lib.to_owned(),
            read_elf(&data.stdout).with_context(|| format!("{}: {entry}", apk.display()))?,
        );
    }
    ensure!(!out.is_empty(), "{} has no {LIB_DIR}*.so", apk.display());
    Ok(out)
}

/// Per library: its imports, classified.
pub fn audit(
    libs: &BTreeMap<String, Elf>,
    rows: &Rows,
    surfaces: &BTreeMap<&'static str, BTreeSet<String>>,
) -> BTreeMap<String, Vec<(String, Class)>> {
    libs.iter()
        .map(|(lib, e)| {
            let app: BTreeMap<String, BTreeSet<String>> = libs
                .iter()
                .filter(|(l, _)| *l != lib)
                .map(|(l, o)| (l.clone(), o.exports.clone()))
                .collect();
            let classes = e
                .imports
                .iter()
                .map(|(n, w)| (n.clone(), classify(n, *w, &e.needed, &app, rows, surfaces)))
                .collect();
            (lib.clone(), classes)
        })
        .collect()
}

/// A gated (strong) remaining import: trapped, or unknown and not weak.
fn remaining(c: &Class) -> bool {
    matches!(c, Class::Trapped(..) | Class::Unknown { weak: false })
}

/// Prints one APK's report; returns its remaining imports as `lib: name (class; owner)`.
fn report(
    apk: &Path,
    result: &BTreeMap<String, Vec<(String, Class)>>,
    verbose: bool,
) -> Vec<String> {
    println!("== {}", apk.display());
    let mut left = Vec::new();
    for (lib, imports) in result {
        let count = |f: fn(&Class) -> bool| imports.iter().filter(|(_, c)| f(c)).count();
        println!(
            "{lib}: {} imports: bound {} (app {}, table {}, guest lib {}), trapped {}, unknown {} (+{} weak)",
            imports.len(),
            count(|c| matches!(c, Class::App(_) | Class::Bound(_) | Class::Guest(_))),
            count(|c| matches!(c, Class::App(_))),
            count(|c| matches!(c, Class::Bound(_))),
            count(|c| matches!(c, Class::Guest(_))),
            count(|c| matches!(c, Class::Trapped(..))),
            count(|c| matches!(c, Class::Unknown { weak: false })),
            count(|c| matches!(c, Class::Unknown { weak: true })),
        );
        for (name, c) in imports {
            let line = match c {
                Class::Trapped(so, why) => format!("trapped {so}:{name} ({why}) -> {}", owner(c)),
                Class::Unknown { weak } => format!(
                    "unknown{} {name} -> {}",
                    if *weak { " weak" } else { "" },
                    owner(c)
                ),
                _ if verbose => format!("{c:?} {name}"),
                _ => continue,
            };
            println!("  {line}");
            if remaining(c) {
                left.push(format!("{lib}: {line}"));
            }
        }
    }
    left
}

/// The guest libraries besides bionic's three (ndk_surface `MAPS`) that the arm64 NB build stages (goals `nb:liblog`, `nb:libz`): the QEMU guest runs them translated. AOSP `.map.txt` per soname.
const GUEST_MAPS: &[(&str, &str)] = &[
    ("liblog.so", "system/logging/liblog/liblog.map.txt"),
    ("libz.so", "external/zlib/libz.map.txt"),
];

/// The guest library surfaces: the NDK names of each guest library's `.map.txt` for the guest arch.
fn surfaces(root: &Path) -> Result<BTreeMap<&'static str, BTreeSet<String>>> {
    let layout = Layout::of(root)?;
    let mut out = BTreeMap::new();
    for (so, rel) in crate::ndk_surface::MAPS.iter().chain(GUEST_MAPS) {
        let p = layout.locate(&Path::new("aosp").join(rel)).dir;
        let text = std::fs::read_to_string(&p).with_context(|| p.display().to_string())?;
        let names = crate::ndk_surface::surface(&text, GUEST_ARCH)
            .with_context(|| p.display().to_string())?
            .into_iter()
            .map(|(_, s)| s)
            .collect();
        out.insert(*so, names);
    }
    Ok(out)
}

pub fn run(root: &Path, args: &Args) -> Result<ExitCode> {
    let ws = Layout::of(root)?.workspace().to_path_buf();
    let gated = if args.apk.is_empty() {
        vec![ws.join(CTR)]
    } else {
        args.apk.clone()
    };
    let info = if args.info.is_empty() {
        let dir = ws.join(BC_DIR);
        let mut v: Vec<PathBuf> = std::fs::read_dir(&dir)
            .with_context(|| dir.display().to_string())?
            .filter_map(|e| e.ok().map(|e| e.path()))
            .filter(|p| p.to_string_lossy().ends_with(BC_SPLIT_SUFFIX))
            .collect();
        v.sort();
        v
    } else {
        args.info.clone()
    };
    let rows = qemu_rows();
    let surfaces = surfaces(root)?;
    let mut fails = Vec::new();
    for apk in &gated {
        let left = report(apk, &audit(&apk_libs(apk)?, &rows, &surfaces), args.verbose);
        if !left.is_empty() {
            fails.push(Failure::gate(&format!(
                "{}: {} remaining: {}",
                apk.display(),
                left.len(),
                left.join(" | ")
            )));
        }
    }
    for apk in &info {
        let left = report(apk, &audit(&apk_libs(apk)?, &rows, &surfaces), args.verbose);
        println!(
            "(informational) {}: {} remaining",
            apk.display(),
            left.len()
        );
    }
    let verdict = Verdict {
        cmd: "app-imports",
        total: Some((gated.len(), "gated apks")),
        skipped: Vec::new(),
        failures: fails,
    };
    println!("{}", verdict.line());
    Ok(if verdict.failures.is_empty() {
        ExitCode::SUCCESS
    } else {
        ExitCode::FAILURE
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    /// A GLES2 import whose row binds in the generated table (Q7-4 gates glClearColor through it).
    const ROW: (&str, &str) = ("libGLESv2.so", "glClearColor");

    fn needed() -> Vec<String> {
        vec!["libGLESv2.so".to_owned(), "libc.so".to_owned()]
    }

    #[test]
    fn bound_row_resolves_and_a_removed_row_is_unknown() {
        let mut rows = qemu_rows();
        let (app, guest) = (BTreeMap::new(), BTreeMap::new());
        let c = classify(ROW.1, false, &needed(), &app, &rows, &guest);
        assert_eq!(c, Class::Bound(ROW.0));
        // break: drop the row from the audited table
        assert!(rows.remove(&ROW).is_some());
        let c = classify(ROW.1, false, &needed(), &app, &rows, &guest);
        assert_eq!(c, Class::Unknown { weak: false });
        assert!(remaining(&c));
    }

    #[test]
    fn order_app_then_needed_then_guest() {
        let rows = qemu_rows();
        let mut app = BTreeMap::new();
        app.insert("libother.so".to_owned(), BTreeSet::from([ROW.1.to_owned()]));
        assert_eq!(
            classify(ROW.1, false, &needed(), &app, &rows, &BTreeMap::new()),
            Class::App("libother.so".to_owned())
        );
        // strlen: bionic code in the guest, not an NBS libc stub
        let mut surfaces = BTreeMap::new();
        surfaces.insert("libc.so", BTreeSet::from(["strlen".to_owned()]));
        assert_eq!(
            classify(
                "strlen",
                false,
                &needed(),
                &BTreeMap::new(),
                &rows,
                &surfaces
            ),
            Class::Guest("libc.so")
        );
        // not NEEDED: not resolved there
        assert_eq!(
            classify("strlen", true, &[], &BTreeMap::new(), &rows, &surfaces),
            Class::Unknown { weak: true }
        );
        assert!(!remaining(&Class::Unknown { weak: true }));
    }

    #[test]
    fn ndk_shim_bound_under_qemu() {
        let rows = qemu_rows();
        let c = classify(
            "AndroidBitmap_lockPixels",
            false,
            &["libjnigraphics.so".to_owned()],
            &BTreeMap::new(),
            &rows,
            &BTreeMap::new(),
        );
        assert!(matches!(c, Class::Bound("libjnigraphics.so")), "{c:?}");
    }
}
